import {esc,intro} from './presentation.mjs';
import {brand} from './layout.mjs';

export function authView({ready,mode='login',door='student',message='',usingNeon=false}) {
 const instructor=door==='instructor';
 const title={login:'Welcome back',signup:'Create your account',recover:'Reset password',password:'Choose a new password'}[mode];
 const subtitle=mode==='signup'&&instructor?'Your account will be reviewed before you can accept learners.':instructor?'Manage your learners and teaching schedule.':'Plan your lessons and see your progress.';
 return `<main class="auth-shell"><section class="auth-story">${brand}<div><div class="eyebrow">YOUR ROAD TO CONFIDENCE</div><h1>Learn the skills.<br>Own the road.</h1><p>Structured plans, guided practice and a clear view of your progress.</p></div><div class="plan-preview-pills"><span class="pill">10-Day · ₹1,500 · 10 credits</span><span class="pill">Monthly · ₹4,000 · 30 credits</span></div><small>DriveX Driving Academy</small></section><section class="auth-panel"><div class="auth-card">${!ready?intro('Setup required','The school needs to configure the service before you can sign in.'):`${(mode==='login'||mode==='signup')&&!usingNeon?`<div class="door-tabs" role="group" aria-label="Account type"><button class="door-btn ${!instructor?'active':''}" data-door="student" aria-pressed="${!instructor}">I'm a Learner</button><button class="door-btn ${instructor?'active':''}" data-door="instructor" aria-pressed="${instructor}">I'm an Instructor</button></div>`:''}${intro(title,subtitle)}<form id="auth-form" class="modal-body">${mode==='signup'?`<label>Full name<input name="name" autocomplete="name" maxlength="100" required></label>${usingNeon?'':`<label>Phone<input name="phone" type="tel" autocomplete="tel" maxlength="30" required></label><label>Account type<select name="role"><option value="student" ${!instructor?'selected':''}>Learner</option><option value="instructor" ${instructor?'selected':''}>Instructor · approval required</option></select></label>`}`:''}${mode!=='password'?'<label>Email<input name="email" type="email" autocomplete="email" required></label>':''}${mode!=='recover'?`<label>Password<input name="password" type="password" minlength="8" autocomplete="${mode==='login'?'current-password':'new-password'}" required></label>`:''}<p class="error" id="auth-error" role="alert"></p><p role="status">${esc(message)}</p><button class="primary full">${mode==='signup'?'Create account':mode==='recover'?'Send reset link':mode==='password'?'Save password':'Sign in'}</button></form><div class="auth-links">${mode==='login'?'<button class="link" data-auth="signup">Create an account</button><button class="link" data-auth="recover">Forgot password?</button>':'<button class="link" data-auth="login">Back to sign in</button>'}</div>`}</div></section></main>`;
}
